//! Real TPC-H, end to end, on both executors.
//!
//! Data is generated by `tpchgen` at a real scale factor — dbgen's schema, distributions and
//! correlations — and written through a real btrblocks compressing pipeline, so decode cost is
//! the cost a real file imposes. Queries are the scan portion of the TPC-H queries in
//! `vortex-bench/sql/tpch/`, transcribed predicate for predicate.
//!
//! The exactness contract is stricter than the synthetic eval's:
//!
//! 1. Both executors read the *same* segments of the *same* written file.
//! 2. Before any timing, every configuration's output is compared to V1's on **dtype, row count,
//!    and ordered content** — a mismatch on any of the three is a hard failure that aborts the
//!    run rather than a row excluded from the table.
//! 3. Only then are the alternating timing iterations run.
//!
//! Run with:
//! `cargo run --release -p vortex-morsel --features _test-harness --bin tpch-eval -- [scale]`

use std::sync::Arc;
use std::time::Duration;
use std::time::Instant;

use vortex::VortexSessionDefault;
use vortex_error::VortexResult;
use vortex_error::vortex_bail;
use vortex_io::runtime::single::block_on;
use vortex_io::session::RuntimeSessionExt;
use vortex_layout::LayoutRef;
use vortex_layout::segments::SegmentSource;
use vortex_morsel::fixtures::write_fixture_no_table;
use vortex_morsel::harness::MorselConfig;
use vortex_morsel::harness::Query;
use vortex_morsel::harness::RunOutcome;
use vortex_morsel::harness::assert_same_rows;
use vortex_morsel::harness::run_morsel;
use vortex_morsel::harness::run_v1;
use vortex_morsel::harness::run_v1_tokio;
use vortex_morsel::harness::run_v1_tokio_with;
use vortex_morsel::nodes::ConjunctMode;
use vortex_morsel::tpch;
use vortex_session::VortexSession;
use vortex_utils::parallelism::get_available_parallelism;

const ITERATIONS: usize = 5;

#[derive(Clone, Copy)]
enum Row {
    V1Single,
    V1Tokio(usize),
    Morsel(MorselConfig),
}

impl Row {
    fn label(&self) -> String {
        match self {
            Row::V1Single => "A  V1 (1 thread)".to_string(),
            Row::V1Tokio(threads) => format!("A' V1 (tokio x{threads})"),
            Row::Morsel(config) => {
                let mode = match config.mode {
                    ConjunctMode::Cascade => "",
                    ConjunctMode::Parallel => ", parallel",
                };
                let morsel = if config.morsel_rows == 0 {
                    "splits".to_string()
                } else if config.morsel_rows == vortex_morsel::driver::DEFAULT_MORSEL_ROWS {
                    "128k".to_string()
                } else {
                    format!("{}r", config.morsel_rows)
                };
                let reuse = if config.share_decodes {
                    ""
                } else {
                    ", no-reuse"
                };
                format!("D  morsel (x{}, {morsel}{mode}{reuse})", config.threads)
            }
        }
    }
}

struct Timing {
    label: String,
    median: Duration,
    rows: usize,
    ttfb: Option<Duration>,
    requests: Option<u64>,
    decodes: Option<u64>,
    reuses: Option<u64>,
    morsels: Option<u64>,
}

fn main() -> VortexResult<()> {
    // The full session: every encoding plugin registered, so the compressing writer can
    // serialise what btrblocks produces and the readers can decode it.
    let session = VortexSession::default();
    let threads = get_available_parallelism().unwrap_or(4);
    let runtime = tokio::runtime::Builder::new_multi_thread()
        .worker_threads(threads)
        .enable_all()
        .build()
        .map_err(|err| vortex_error::vortex_err!("failed to build the tokio runtime: {err}"))?;

    let scale: f64 = std::env::args()
        .nth(1)
        .and_then(|arg| arg.parse().ok())
        .or_else(|| {
            std::env::var("TPCH_SCALE")
                .ok()
                .and_then(|v| v.parse().ok())
        })
        .unwrap_or(0.5);
    let row_block: usize = std::env::var("TPCH_ROW_BLOCK")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(8192);
    // The production default block target. Lowering it produces more, smaller chunks, which is
    // the knob that decides how many morsels a scan is cut into.
    let block_target: u64 = std::env::var("TPCH_BLOCK_BYTES")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(1 << 20);

    println!("# TPC-H scan evaluation: V1 LayoutReader vs the morsel executor");
    println!();

    // 1. Generate real lineitem.
    let gen_start = Instant::now();
    let table = tpch::lineitem(&session, scale, 65_536)?;
    let gen_elapsed = gen_start.elapsed();

    // 2. Write it through the real compressing pipeline.
    let strategy = tpch::write_strategy(row_block, block_target);
    let write_start = Instant::now();
    let columns = tpch::columns(&table, 0, &session)?;
    let ncolumns = columns.len();
    let generated_rows = table.row_count;
    // The generated struct batches are no longer needed once split into columns.
    drop(table);
    // The compressing pipeline spawns CPU work, so the writing session needs a runtime handle.
    let fixture = {
        let session = session.clone();
        block_on(move |handle| {
            let session = session.with_handle(handle);
            async move { write_fixture_no_table(columns, strategy, &session).await }
        })?
    };
    let write_elapsed = write_start.elapsed();
    let segments: Arc<dyn SegmentSource> = Arc::clone(&fixture.segments);

    let splits = vortex_morsel::build_plan(
        &fixture.layout,
        &queries_probe(),
        None,
        ConjunctMode::Cascade,
    )
    .map(|plan| plan.natural_splits().len())
    .unwrap_or(0);
    println!(
        "lineitem SF={scale}: {} rows ({generated_rows} generated), {ncolumns} columns,          {splits} natural splits; generated in {}, written in {}",
        fixture.row_count,
        millis(gen_elapsed),
        millis(write_elapsed)
    );
    println!(
        "written through the btrblocks compressing pipeline (repartition {row_block} rows -> \
         coalesce {block_target}B -> compress -> buffer -> chunk -> flat); no zone maps, no dict \
         layout"
    );
    println!(
        "host: {threads} logical cores; segments in memory; {ITERATIONS} alternating iterations, \
         median reported"
    );
    println!();
    println!("schema: {}", fixture.layout.dtype());
    println!();

    let queries = tpch::lineitem_queries(fixture.layout.dtype())?;

    // Sweep mode: thread-scaling curves and a morsel-size sweep, to decompose *why* the
    // four-thread rows win rather than only reporting that they do.
    if std::env::var("TPCH_SWEEP").is_ok_and(|v| v == "1") {
        return sweep(&runtime, &session, &fixture, &segments, &queries, threads);
    }

    let configs = |threads: usize| {
        vec![
            Row::V1Single,
            Row::V1Tokio(threads),
            Row::Morsel(MorselConfig {
                threads: 1,
                ..Default::default()
            }),
            Row::Morsel(MorselConfig {
                threads: 1,
                share_decodes: false,
                ..Default::default()
            }),
            Row::Morsel(MorselConfig {
                threads,
                ..Default::default()
            }),
            Row::Morsel(MorselConfig {
                threads,
                morsel_rows: 0,
                ..Default::default()
            }),
        ]
    };

    for query in &queries {
        // Exactness first. Any disagreement aborts: on a real query over real data, a
        // configuration that does not reproduce V1's output exactly is a bug, not a table row.
        let oracle = run_v1(&session, &fixture.layout, &segments, query)?;
        let dtype = query
            .projection
            .bind(fixture.layout.dtype())?
            .dtype()
            .clone();

        for row in configs(threads) {
            let outcome = run_once(&runtime, &session, &fixture.layout, &segments, query, row)?;
            if outcome.rows != oracle.rows {
                vortex_bail!(
                    "{} / {}: row count {} != V1's {}",
                    query.name,
                    row.label(),
                    outcome.rows,
                    oracle.rows
                );
            }
            assert_same_rows(&session, &dtype, &oracle, &outcome).map_err(|err| {
                err.with_context(format!("{} / {} exactness", query.name, row.label()))
            })?;
        }

        let validated = configs(threads);
        let mut samples: Vec<Vec<RunOutcome>> = validated.iter().map(|_| Vec::new()).collect();
        for _ in 0..ITERATIONS {
            for (idx, row) in validated.iter().enumerate() {
                samples[idx].push(run_once(
                    &runtime,
                    &session,
                    &fixture.layout,
                    &segments,
                    query,
                    *row,
                )?);
            }
        }

        let timings: Vec<Timing> = validated
            .iter()
            .zip(samples)
            .map(|(row, mut runs)| {
                runs.sort_by_key(|run| run.wall);
                let median = &runs[runs.len() / 2];
                Timing {
                    label: row.label(),
                    median: median.wall,
                    rows: median.rows,
                    ttfb: median.time_to_first_batch,
                    requests: median.stats.as_ref().map(|s| s.io_requests),
                    decodes: median.stats.as_ref().map(|s| s.decodes),
                    reuses: median.stats.as_ref().map(|s| s.decode_reuses),
                    morsels: median.stats.as_ref().map(|s| s.morsels),
                }
            })
            .collect();

        report(query, &timings, fixture.row_count);
    }

    println!("Every configuration reproduced V1's dtype, row count and ordered content exactly.");
    Ok(())
}

/// A whole-row projection, used only to count the file's natural splits for the header line.
fn queries_probe() -> vortex_array::expr::Expression {
    vortex_array::expr::root()
}

/// Decompose the four-thread win, and probe oversubscription.
///
/// This host reports `Thread(s) per core: 1`, so physical and logical cores are the same number
/// and "one driving thread per physical core" is exactly the `D x4` row. What that leaves open is
/// whether going *past* one thread per core helps. It matters because the two executors sit at
/// very different points already: the morsel driver runs one morsel per thread, so four threads
/// means four concurrent units, while V1 spawns `concurrency` split tasks per worker (default 4),
/// so four workers means sixteen concurrent units on four threads. V1 is already heavily
/// oversubscribed at the task level; the morsel driver is not oversubscribed at all.
fn sweep(
    runtime: &tokio::runtime::Runtime,
    session: &VortexSession,
    fixture: &vortex_morsel::fixtures::Fixture,
    segments: &Arc<dyn SegmentSource>,
    queries: &[Query],
    cores: usize,
) -> VortexResult<()> {
    println!("## Driving threads vs cores ({cores} physical cores, 1 thread per core)");
    println!();
    println!(
        "Morsel driver: one morsel in flight per thread. `x{cores}` is one thread per physical \
         core; beyond that the host is oversubscribed."
    );
    println!();

    let thread_counts = [1usize, 2, cores, cores * 2, cores * 4];
    print!("| query |");
    for n in &thread_counts {
        print!(" D x{n} |");
    }
    println!(" best | vs D x{cores} |");
    print!("|---|");
    for _ in 0..thread_counts.len() + 2 {
        print!("--:|");
    }
    println!();

    for query in queries {
        let mut walls = Vec::new();
        for &n in &thread_counts {
            walls.push(median(ITERATIONS, || {
                run_morsel(
                    session,
                    &fixture.layout,
                    segments,
                    query,
                    MorselConfig {
                        threads: n,
                        ..Default::default()
                    },
                )
            })?);
        }
        let at_cores = walls[2];
        let best = walls
            .iter()
            .enumerate()
            .min_by_key(|(_, w)| **w)
            .map(|(idx, w)| (thread_counts[idx], *w))
            .unwrap_or((cores, at_cores));
        print!("| {} |", query.name);
        for wall in &walls {
            print!(" {} |", millis(*wall));
        }
        println!(
            " x{} | {:.2}x |",
            best.0,
            best.1.as_secs_f64() / at_cores.as_secs_f64()
        );
    }
    println!();

    println!("## V1 concurrent units: {cores} workers x per-worker split concurrency");
    println!();
    println!(
        "V1's parallelism is workers x concurrency. This sweeps the second factor to check the \
         baseline is not simply mis-tuned."
    );
    println!();
    print!("| query | V1 x1 |");
    for c in [1usize, 2, 4, 8, 16] {
        print!(" tok{cores} c={c} |");
    }
    println!(" best |");
    print!("|---|--:|");
    for _ in 0..6 {
        print!("--:|");
    }
    println!();

    for query in queries {
        let single = median(ITERATIONS, || {
            run_v1(session, &fixture.layout, segments, query)
        })?;
        let mut walls = Vec::new();
        for c in [1usize, 2, 4, 8, 16] {
            walls.push(median(ITERATIONS, || {
                run_v1_tokio_with(runtime, session, &fixture.layout, segments, query, Some(c))
            })?);
        }
        let best = walls.iter().copied().min().unwrap_or(single);
        print!("| {} | {} |", query.name, millis(single));
        for wall in &walls {
            print!(" {} |", millis(*wall));
        }
        println!(" {} |", millis(best));
    }
    println!();

    println!("## Morsel size at {cores} threads: is there enough work to fill the cores?");
    println!();
    println!(
        "`n` is the morsel count, `n/core` is morsels per driving thread. Below roughly 4 \
         morsels per core the tail of the last morsel is a large fraction of the run and load \
         balance falls apart, whatever the per-morsel overhead is."
    );
    println!();
    let sizes: [(u64, &str); 8] = [
        (0, "splits"),
        (16_384, "16k"),
        (32_768, "32k"),
        (65_536, "64k"),
        (131_072, "128k"),
        (262_144, "256k"),
        (1_048_576, "1M"),
        (u64::MAX / 2, "single"),
    ];
    print!("| query |");
    for (_, label) in &sizes {
        print!(" {label} |");
    }
    println!();
    print!("|---|");
    for _ in 0..sizes.len() {
        print!("--:|");
    }
    println!();

    for query in queries {
        print!("| {} |", query.name);
        for (size, _) in &sizes {
            let config = MorselConfig {
                threads: cores,
                morsel_rows: *size,
                ..Default::default()
            };
            let probe = run_morsel(session, &fixture.layout, segments, query, config)?;
            let count = probe.stats.as_ref().map(|s| s.morsels).unwrap_or(0);
            let wall = median(ITERATIONS, || {
                run_morsel(session, &fixture.layout, segments, query, config)
            })?;
            let per_core = count as f64 / cores as f64;
            print!(" {} n={count} ({per_core:.1}/core) |", millis(wall));
        }
        println!();
    }
    println!();

    println!("## Where the single-threaded time goes");
    println!();
    println!(
        "`1 morsel` drives the whole scan as one unit: no per-morsel reset, planning, cutting or \
         emission, and no cross-morsel sharing to do. Whatever it costs is decode plus predicate \
         and gather kernels — work identical to V1's. The gap between it and the per-split column \
         is the executor's entire scheduling overhead."
    );
    println!();
    println!(
        "| query | V1 x1 | D x1 per-split | D x1 one morsel | scheduling overhead | kernel-bound share |"
    );
    println!("|---|--:|--:|--:|--:|--:|");
    for query in queries {
        let v1 = median(ITERATIONS, || {
            run_v1(session, &fixture.layout, segments, query)
        })?;
        let split = median(ITERATIONS, || {
            run_morsel(
                session,
                &fixture.layout,
                segments,
                query,
                MorselConfig {
                    threads: 1,
                    ..Default::default()
                },
            )
        })?;
        let single = median(ITERATIONS, || {
            run_morsel(
                session,
                &fixture.layout,
                segments,
                query,
                MorselConfig {
                    threads: 1,
                    morsel_rows: u64::MAX / 2,
                    ..Default::default()
                },
            )
        })?;
        println!(
            "| {} | {} | {} | {} | {:.1}% | {:.0}% |",
            query.name,
            millis(v1),
            millis(split),
            millis(single),
            (split.as_secs_f64() - single.as_secs_f64()) / split.as_secs_f64() * 100.0,
            single.as_secs_f64() / v1.as_secs_f64() * 100.0,
        );
    }
    println!();
    Ok(())
}

fn median(
    iterations: usize,
    mut run: impl FnMut() -> VortexResult<RunOutcome>,
) -> VortexResult<Duration> {
    let mut walls = Vec::with_capacity(iterations);
    for _ in 0..iterations {
        walls.push(run()?.wall);
    }
    walls.sort_unstable();
    Ok(walls[walls.len() / 2])
}

fn run_once(
    runtime: &tokio::runtime::Runtime,
    session: &VortexSession,
    layout: &LayoutRef,
    segments: &Arc<dyn SegmentSource>,
    query: &Query,
    row: Row,
) -> VortexResult<RunOutcome> {
    match row {
        Row::V1Single => run_v1(session, layout, segments, query),
        Row::V1Tokio(_) => run_v1_tokio(runtime, session, layout, segments, query),
        Row::Morsel(config) => run_morsel(session, layout, segments, query, config),
    }
}

fn report(query: &Query, timings: &[Timing], total_rows: u64) {
    let baseline = timings
        .iter()
        .find(|t| t.label.starts_with("A  "))
        .map(|t| t.median)
        .unwrap_or_default();
    let selectivity = timings
        .first()
        .map(|t| t.rows as f64 / total_rows.max(1) as f64 * 100.0)
        .unwrap_or(0.0);

    println!(
        "### {} — {} rows out ({:.2}% selectivity)",
        query.name,
        timings.first().map(|t| t.rows).unwrap_or(0),
        selectivity
    );
    println!();
    println!("| executor | wall | vs V1 | ttfb | morsels | reqs | decodes | reuses |");
    println!("|---|--:|--:|--:|--:|--:|--:|--:|");
    for timing in timings {
        let ratio = if baseline.is_zero() {
            "—".to_string()
        } else {
            format!(
                "{:.2}x",
                timing.median.as_secs_f64() / baseline.as_secs_f64()
            )
        };
        println!(
            "| {} | {} | {} | {} | {} | {} | {} | {} |",
            timing.label,
            millis(timing.median),
            ratio,
            timing.ttfb.map(millis).unwrap_or_else(|| "—".to_string()),
            opt(timing.morsels),
            opt(timing.requests),
            opt(timing.decodes),
            opt(timing.reuses),
        );
    }
    println!();
}

fn millis(duration: Duration) -> String {
    format!("{:.3}ms", duration.as_secs_f64() * 1000.0)
}

fn opt(value: Option<u64>) -> String {
    value.map(|v| v.to_string()).unwrap_or_else(|| "—".into())
}
